      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "The certainty of evidence for the three primary outcomes reduction in anxiety, reduction in depression, and improvement in psychological well-being was assessed",
      "reason": "Synthesis groups are implied by outcome domains (anxiety, depression, well-being) and intervention types (e.g., multimodal vs text-only CAs), but groups are not explicitly specified and linked to review objective comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Secondary sources such as systematic reviews and meta-analyses were excluded to avoid data duplication and maintain a focus on primary empirical research.",
      "reason": "A rationale is provided for the notable restriction excluding secondary sources."
    }
  ],
  "confidence": 88
}

